import networkx as nx
import geopandas as gpd
from shapely.geometry import Point

def optimize_emergency_routes(road_network, fire_stations, hospitals_geojson, snap_tolerance_meters):
    """
    Optimizes emergency response routes by calculating shortest paths from fire stations to hospitals.

    Args:
        road_network (gpd.GeoDataFrame): Road network shapefile in EPSG:4326.
        fire_stations (gpd.GeoDataFrame): Fire station locations in EPSG:4326.
        hospitals_geojson (dict): GeoJSON data for hospital locations.
        snap_tolerance_meters (float): Tolerance for snapping endpoints during graph construction.

    Returns:
        tuple: A tuple containing:
            - dict: A dictionary where keys are fire station names and values are the shortest path distances to hospitals.
            - str: The name of the fire station with the maximum average travel time to all hospitals.
    """

    # 1. Convert road network to a graph
    graph = nx.Graph()
    for feature in road_network.geometry:
        graph.add_node(feature.id)
    for connection in road_network.geometry.intersection(road_network.geometry):
        graph.add_edge(connection.source, connection.target)

    # 2. Snap endpoints
    for node in graph.nodes():
        node_geom = road_network[road_network.geometry.intersects(Point(node['x'], node['y']))].loc[road_network.geometry.intersects(Point(node['x'], node['y'])).idxmin()]['geometry']
        if node_geom.is_empty:
            continue
        node['x'], node['y'] = node_geom.x, node_geom.y

    # 3. Calculate shortest paths
    shortest_paths = {}
    for station in fire_stations['geometry']:
        hospital_points = [Point(h['geometry']['coordinates']) for h in hospitals_geojson['features']]
        distances = {}
        for hospital in hospital_points:
            try:
                path = nx.shortest_path(graph, source=station['geometry']['coordinates'], target=hospital.x, weight='length')
                distance = nx.shortest_path_length(graph, source=station['geometry']['coordinates'], target=hospital.x, weight='length')
                distances[hospital.x] = distance
            except nx.NetworkXNoPath:
                distances[hospital.x] = float('inf')
        shortest_paths[station['properties']['name']] = distances

    # 4. Identify the station with the maximum average travel time
    avg_travel_times = {}
    for station_name, distances in shortest_paths.items():
        total_time = sum(distances.values())
        avg_travel_times[station_name] = total_time / len(distances)

    best_station = max(avg_travel_times, key=avg_travel_times.get)

    return shortest_paths, best_station

if __name__ == '__main__':
