def clean_parcel_data(parcel_data_sample):
    """
    Cleans parcel data by reprojecting, fixing topology, standardizing attributes,
    and exporting as GeoJSON.

    Args:
        parcel_data_sample (dict): A dictionary containing the parcel data
                                    in FeatureCollection format.

    Returns:
        str: A GeoJSON string representing the cleaned parcel data.
    """

    gdf = gpd.GeoDataFrame.from_features(parcel_data_sample['features'], crs="EPSG:4326")

    # 1. Reproject to EPSG:26910
    gdf = gdf.to_crs(epsg=26910)

    # 2. Fix Topology
    gdf = gdf.buffer(0.0001)
    gdf = gdf.make_valid()

    # 3. Standardize Zoning Attribute
    gdf['zoning'] = gdf['zoning'].map(attribute_mapping)

    # 4. Export as GeoJSON
    cleaned_geojson = gdf.to_json(orient="records")

    return cleaned_geojson

