import geopandas as gpd
from shapely.geometry import Point

def analyze_sensor_zones(sensor_data, protected_zones):
    """
    Analyzes sensor points to identify those within protected zones.

    Args:
        sensor_data (FeatureCollection): Sensor point data with CRS.
        protected_zones (FeatureCollection): Protected zone polygons with CRS.

    Returns:
        tuple: A tuple containing:
            - dict: A dictionary of point counts per zone.
            - int: The total number of points flagged as within a zone.
    """

    try:
        # Validate CRS
        sensor_crs = sensor_data.crs
        protected_crs = protected_zones.crs
        if sensor_crs != protected_crs:
            print(f"CRS mismatch: Sensor CRS ({sensor_crs}) != Protected Zone CRS ({protected_crs}).")
            return {}, 0

        # Reproject sensor data to protected zone CRS
        protected_zones_proj = protected_zones.to_crs(sensor_crs)
        sensor_points = gpd.GeoDataFrame(sensor_data, crs=sensor_crs)
        sensor_points['geometry'] = sensor_points['geometry'].apply(Point)
        sensor_points_proj = sensor_points.to_crs(protected_crs)

        # Spatial query
        zone_counts = {}
        total_flagged = 0
        for zone in protected_zones_proj.zones.unique():
            points_in_zone = sensor_points_proj[sensor_points_proj.geometry.within(protected_zones_proj[zone])]
            zone_counts[zone] = len(points_in_zone)
            total_flagged += len(points_in_zone)

        return zone_counts, total_flagged

    except Exception as e:
        print(f"An error occurred: {e}")
        return {}, 0

